RUNTIME_RELATIVE_ROOT = Path("android/.supernote-module/v2-runtime")


def generated_runtime_files(registry: PluginRuntimeRegistry) -> dict[str, str]:
    """Return deterministic generated files for one compiled plugin component."""

    feature_rows = "\n".join(
        "    {"
        + json.dumps(entry.feature.feature_id)
        + ", "
        + json.dumps(entry.feature.public_name)
        + "},"
        for entry in registry.features
    )
    if not feature_rows:
        feature_rows = "    // No generated features are currently registered."
    component = registry.component_name
    registration_component = f"{component}_registration"
    registrar_property = f"supernote.v2.registrar.{component}.v1"
    jvm_roots = [
        f"local_modules/{entry.feature.npm_name}/{entry.feature.roots.jvm}"
        for entry in registry.features
    ]
    native_roots = [
        f"local_modules/{entry.feature.npm_name}/{entry.feature.roots.native}"
        for entry in registry.features
    ]
    jvm_root_rows = "\n".join(
        f"    new File(supernotePluginRoot, {json.dumps(path)}),"
        for path in jvm_roots
    )
    native_root_rows = "\n".join(
        f"    new File(supernotePluginRoot, {json.dumps(path)}),"
        for path in native_roots
    )
    cmake_native_roots = "\n".join(
        f'    "${{CMAKE_CURRENT_LIST_DIR}}/../../../{path}"'
        for path in native_roots
    )
    ksp_root_args = "\n".join(
        "    arg("
        + repr(f"supernoteFeatureRoot_{index:08d}")
        + ", "
        + json.dumps(
            f"{entry.feature.feature_id}\tlocal_modules/"
            f"{entry.feature.npm_name}/{entry.feature.roots.jvm}"
        )
        + ")"
        for index, entry in enumerate(registry.features)
    )
    cmake = f"""# Generated by supernote_module_generator. Do not edit.
cmake_minimum_required(VERSION 3.22.1)
project({component} LANGUAGES C CXX)

if(NOT DEFINED SUPERNOTE_VARIANT)
  message(FATAL_ERROR "SUPERNOTE_VARIANT must be debug or release")
endif()

set(SUPERNOTE_NATIVE_ROOTS
{cmake_native_roots}
)
set(SUPERNOTE_USER_SOURCES)
foreach(SUPERNOTE_NATIVE_ROOT IN LISTS SUPERNOTE_NATIVE_ROOTS)
  file(GLOB_RECURSE SUPERNOTE_FEATURE_SOURCES CONFIGURE_DEPENDS
      "${{SUPERNOTE_NATIVE_ROOT}}/*.c"
      "${{SUPERNOTE_NATIVE_ROOT}}/*.cc"
      "${{SUPERNOTE_NATIVE_ROOT}}/*.cpp"
      "${{SUPERNOTE_NATIVE_ROOT}}/*.cxx")
  list(APPEND SUPERNOTE_USER_SOURCES ${{SUPERNOTE_FEATURE_SOURCES}})
endforeach()
if(NOT DEFINED SUPERNOTE_GENERATED_ROOT)
  set(SUPERNOTE_GENERATED_ROOT
      "${{CMAKE_CURRENT_LIST_DIR}}/build/generated/supernote")
endif()
file(GLOB SUPERNOTE_GENERATED_BINDINGS CONFIGURE_DEPENDS
    "${{SUPERNOTE_GENERATED_ROOT}}/${{SUPERNOTE_VARIANT}}/jni/*.cpp")
if(NOT SUPERNOTE_GENERATED_BINDINGS)
  message(FATAL_ERROR "Supernote generated JSI bindings are missing")
endif()

add_library({component} SHARED
    src/feature_registry.cpp
    src/runtime_bootstrap.cpp
    src/runtime_services.cpp
    ${{SUPERNOTE_USER_SOURCES}}
    ${{SUPERNOTE_GENERATED_BINDINGS}}
)

# This dependency-free bridge is loaded from a unique path by each plugin
# ClassLoader. It contains no runtime services; it only enters the one
# process-loaded runtime component so that component can register JNI methods
# on the replacement ClassLoader.
add_library({registration_component} SHARED
    src/runtime_registration_bridge.c
)

find_package(Threads REQUIRED)
find_package(ReactAndroid REQUIRED CONFIG)
find_package(fbjni REQUIRED CONFIG)
target_compile_features({component} PRIVATE cxx_std_23)
set_target_properties({component} PROPERTIES C_STANDARD 23 C_STANDARD_REQUIRED YES)
target_include_directories(
    {component} PRIVATE ${{SUPERNOTE_NATIVE_ROOTS}}
    "${{CMAKE_CURRENT_LIST_DIR}}/src"
    "${{CMAKE_CURRENT_LIST_DIR}}/include")
target_link_libraries(
    {component} PRIVATE
    Threads::Threads
    ReactAndroid::jsi
    ReactAndroid::reactnative
    fbjni::fbjni
    log)
set_target_properties(
    {registration_component} PROPERTIES
    C_STANDARD 23
    C_STANDARD_REQUIRED YES)
"""
